    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    box = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(box), len(box[0])

    inside = {}
    outside = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color <= 1:
                continue
            if r0 <= r <= r1 and c0 <= c <= c1:
                inside.setdefault(color, []).append((r - r0, c - c0))
            else:
                outside.setdefault(color, []).append((r, c))

    # Colors appearing exactly once inside the rectangle are its corner markers.
    anchors = {color: pts[0] for color, pts in inside.items()
               if len(pts) == 1 and color in outside}
    outer = {color: pts[0] for color, pts in outside.items()
             if color in anchors}

    def normalized(points):
        rs = [p[0] for p in points.values()]
        cs = [p[1] for p in points.values()]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)
        return {
            color: ((p[0] - rmin) / (rmax - rmin) if rmax != rmin else 0.5,
                    (p[1] - cmin) / (cmax - cmin) if cmax != cmin else 0.5)
            for color, p in points.items()
        }

    outer_norm = normalized(outer)

    # Each candidate maps (r,c) to an output coordinate.
    candidates = [
        (H, W, lambda r, c: (r, c)),
        (H, W, lambda r, c: (r, W - 1 - c)),
        (H, W, lambda r, c: (H - 1 - r, c)),
        (H, W, lambda r, c: (H - 1 - r, W - 1 - c)),
        (W, H, lambda r, c: (c, r)),
        (W, H, lambda r, c: (W - 1 - c, H - 1 - r)),
        (W, H, lambda r, c: (c, H - 1 - r)),
        (W, H, lambda r, c: (W - 1 - c, r)),
    ]

    best_cost = float("inf")
    chosen = candidates[0]
    for oh, ow, mapping in candidates:
        cost = 0.0
        for color, (r, c) in anchors.items():
            nr, nc = mapping(r, c)
            pos = (nr / max(1, oh - 1), nc / max(1, ow - 1))
            target = outer_norm[color]
            cost += (pos[0] - target[0]) ** 2 + (pos[1] - target[1]) ** 2
        if cost < best_cost:
            best_cost, chosen = cost, (oh, ow, mapping)

    oh, ow, mapping = chosen
    out = [[0] * ow for _ in range(oh)]
    for r in range(H):
        for c in range(W):
            nr, nc = mapping(r, c)
            out[nr][nc] = box[r][c]

    # The outside markers specify the colors at the corresponding corner
    # positions, so transfer those labels to the transformed marker cells.
    transformed = {}
    for color, (r, c) in anchors.items():
        nr, nc = mapping(r, c)
        transformed[color] = (nr / max(1, oh - 1), nc / max(1, ow - 1))

    remaining = set(transformed)
    for color, target in outer_norm.items():
        if not remaining:
            break
        match = min(
            remaining,
            key=lambda key: (transformed[key][0] - target[0]) ** 2
                           + (transformed[key][1] - target[1]) ** 2
        )
        nr, nc = mapping(*anchors[match])
        out[nr][nc] = color
        remaining.remove(match)

    return out
